				!(move.isZ && move.category !== 'Status') && !(move.name === 'Tera Blast' && pokemon.terastallized)) {
				move.type = 'Dragon';
				move.typeChangerBoosted = this.effect;
			}
		}

onBasePower.callbackSource:
onBasePower(basePower, pokemon, target, move) {
			if (move.typeChangerBoosted === this.effect) return this.chainModify([4915, 4096]);
		}

onWeatherModifyDamage.callbackSource:
onWeatherModifyDamage(damage, attacker, defender, move) {
			(this.dex.conditions.getByID('sunnyday' as ID) as any).onWeatherModifyDamage
				.call(this, damage, attacker, defender, move);
			return damage; // fast exit from event
		}

onDamagingHit.callbackSource:
onDamagingHit(damage, target, source, move) {
			source.trySetStatus('brn', target);
		}

onSourceAfterFaint.callbackSource:
onSourceAfterFaint(length, target, source, effect) {
			if (effect?.effectType === 'Move') {
				const bestStat = source.getBestStat(true, true);
				this.boost({ [bestStat]: length }, source);
			}
		}

onModifyAtk.callbackSource:
onModifyAtk(atk, attacker, defender, move) {
			if (move.type === 'Fire') {
				this.debug('Fire Mane boost');
				return this.chainModify(1.5);
			}
		}

onModifySpA.callbackSource:
onModifySpA(atk, attacker, defender, move) {
			if (move.type === 'Fire') {
				this.debug('Fire Mane boost');
				return this.chainModify(1.5);
			}
		}

onSourceModifyDamage.callbackSource:
onSourceModifyDamage(damage, source, target, move) {
			if (move.flags['contact']) return this.chainModify(0.5);
		}
